<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Activity Logs</title><style>body{font:15px Arial;background:#f4f6fa;color:#172b43}.wrap{max-width:1200px;margin:30px auto;padding:0 15px}.card{background:#fff;padding:22px;border-radius:12px;margin:16px 0;overflow:auto}input,select{padding:10px;border:1px solid #ccd5df;border-radius:6px;margin:4px}button,a{background:#173d65;color:#fff;padding:9px 13px;border:0;border-radius:7px;text-decoration:none;cursor:pointer}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:11px;border-bottom:1px solid #eee;font-size:13px}</style></head><body><main class="wrap"><h1>System Activity Logs</h1><p><a href="{{ route('dashboard') }}">Dashboard</a></p><div class="card"><form method="GET"><input name="search" value="{{ request('search') }}" placeholder="Search activity description"><select name="module"><option value="">All modules</option>@foreach(['branches','employees','products','inventory','sales','customers','expenses','settings'] as $m)<option value="{{ $m }}" @selected(request('module')===$m)>{{ ucfirst($m) }}</option>@endforeach</select><button>Filter</button></form><table><tr><th>Date</th><th>User</th><th>Branch</th><th>Module</th><th>Action</th><th>Description</th><th>IP</th></tr>@forelse($logs as $l)<tr><td>{{ $l->created_at->format('d M Y H:i:s') }}</td><td>{{ $l->user?->name ?? 'System' }}</td><td>{{ $l->branch?->name ?? '—' }}</td><td>{{ $l->module }}</td><td>{{ $l->action }}</td><td>{{ $l->description }}</td><td>{{ $l->ip_address }}</td></tr>@empty<tr><td colspan="7">No activity logs found.</td></tr>@endforelse</table>{{ $logs->links() }}</div></main></body></html>